mapper.select:
SELECT id, service_name, direction, purpose, caller_name, authorization_scope, authorization_scope_value,
       owner_id, status, created_at, updated_at
FROM sys_interface_service
WHERE service_name = #{serviceName}
  AND caller_name = #{callerName}

mapper.insert:
INSERT INTO sys_interface_service (
