    owner_id, status
) VALUES (
    #{service.id}, #{service.serviceName}, #{service.direction}, #{service.purpose}, #{service.callerName},
    #{service.authorizationScope}, #{service.authorizationScopeValue, jdbcType=VARCHAR}, #{service.ownerId},
    #{service.status}
)
